/**
 * Content-free span attributes for `computerUse` tool calls.
 *
 * Computer use args hold typed text and screen coordinates, so the collector
 * exports them only under `toolContent`. These attributes keep the action
 * shape visible without that opt-in. On the cloud agent path one
 * `computerUse` call is one action, so its tool span is the action span.
 */
import { isRecord } from "../is-record.js";
export function computerUseRequestAttrs(toolName, args) {
    if (toolName !== "computerUse" || !isRecord(args) || !Array.isArray(args.actions)) {
        return {};
    }
    // The SDK adapter emits only known action types, so `type` is a fixed
    // literal and carries no content.
    const types = args.actions.map((action) => isRecord(action) && typeof action.type === "string" ? action.type : "other");
    return { "agent_sdk.computer.actions": types.join(",") };
}
// An error result is rebuilt from the thrown error and reports zero
// durations, so only a success result carries executor timing.
export function computerUseResultAttrs(result) {
    const { toolName, output, isError } = result;
    if (toolName !== "computerUse" || isError || !isRecord(output)) {
        return {};
    }
    return {
        "agent_sdk.computer.executor_duration_ms": typeof output.durationMs === "number" ? output.durationMs : undefined,
        "agent_sdk.computer.settle_ms": typeof output.settleMs === "number" ? output.settleMs : undefined,
    };
}
